package com.booksyde.service; import com.booksyde.dto.request.UpdateProfileRequest; import com.booksyde.dto.response.ProfileResponse; import com.booksyde.entity.ProfileEntity; import com.booksyde.exception.ResourceNotFoundException; import com.booksyde.repository.ProfileRepository; import java.util.UUID; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service public class ProfileService {private final ProfileRepository repo; public ProfileService(ProfileRepository repo){this.repo=repo;} @Transactional(readOnly=true) public ProfileResponse get(UUID id){var p=repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Perfil não encontrado.")); return map(p);} @Transactional public ProfileResponse update(UUID id,UpdateProfileRequest r){var p=repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Perfil não encontrado.")); p.update(r.displayName(),r.avatarUrl()); return map(p);} private ProfileResponse map(ProfileEntity p){return new ProfileResponse(p.getId(),p.getDisplayName(),p.getAvatarUrl());}}
